<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><style>body{font-family:"DejaVu Sans";direction:rtl;font-size:11px}table{width:100%;border-collapse:collapse;margin-top:15px}th,td{border:1px solid #bbb;padding:6px}.head{border-bottom:2px solid #222;padding-bottom:10px}.totals{width:45%;margin-right:auto}</style></head><body><div class="head"><h2>پیش‌فاکتور فروش عمده</h2><div>شماره: {{ $quote->number }} | تاریخ: {{ $jalali->format($quote->created_at) }} | اعتبار تا: {{ $jalali->format($quote->expires_at,false) }}</div></div><p><b>فروشنده:</b> {{ $seller['name'] }} {{ $seller['national_id']?' | شناسه ملی: '.$seller['national_id']:'' }}</p><p><b>خریدار:</b> {{ $quote->legal_name ?: $quote->name }} | {{ $quote->mobile }} @if($quote->national_id) | شناسه ملی: {{ $quote->national_id }} @endif</p><table><thead><tr><th>#</th><th>کالا</th><th>SKU</th><th>تعداد</th><th>فی</th><th>جمع</th></tr></thead><tbody>@foreach($items as $i=>$item)<tr><td>{{ $i+1 }}</td><td>{{ $item->name }}</td><td>{{ $item->sku }}</td><td>{{ number_format($item->quantity) }}</td><td>{{ number_format($item->unit_price) }}</td><td>{{ number_format($item->line_total) }}</td></tr>@endforeach</tbody></table><table class="totals"><tr><td>جمع</td><td>{{ number_format($quote->subtotal) }}</td></tr><tr><td>تخفیف</td><td>{{ number_format($quote->discount_total) }}</td></tr><tr><td><b>قابل پرداخت</b></td><td><b>{{ number_format($quote->total) }} ریال</b></td></tr></table><p>{{ $quote->note }}</p></body></html>
